function syntaxTrialEnabled() {
    return typeof window !== 'undefined' && window.__FLUENCY_ENV__ === 'staging'
        && new URLSearchParams(window.location?.search || '').get('fwSyntaxTrial') === '1';
}

// Backward-compatibility: ensure .uses aliases
for (const dict of [PORTUGUESE_GRAMMAR_WORDS, SPANISH_GRAMMAR_WORDS]) {
    for (const entry of Object.values(dict)) {
        if (!entry.uses) entry.uses = entry.relations;
        // Every pattern of a contraction (del, naquele) takes contraction colour.
        if (entry.parts) for (const rel of entry.relations || []) rel._contraction = true;
    }
}

const ROLE_NAMES = {
    prep: 'preposition',
    article: 'article',
    subject_pron: 'subject',
    direct_obj: 'direct object',
    indirect_obj: 'indirect object',
    reflexive: 'reflexive',
    rel_pron: 'relative',
    coord_conj: 'coordination',
    subord_conj: 'subordination',
    adverbial: 'adverbial',
    adv_connector: 'connector',
    possessive: 'possessive',
    demonstrative: 'demonstrative',
    indefinite: 'indefinite',
    quantifier: 'quantifier',
    negation: 'negation',
    focus_particle: 'focus particle',
    interrogative: 'question',
    comparative: 'comparison',
    contraction: 'contraction',
    clitic: 'clitic'
};


// Reuse the app palette and provenance component without a circular import.
let fwPresentation = {};
export function configureFunctionWordPresentation(options) {
    fwPresentation = options || {};
}
// The word's own colour in a pattern: contraction orange whenever the pattern
// is a contraction (del, naquele, or nos as em + os), else its part of speech.
function fwAccentPos(relation) {
    if (!relation) return '';
    if (relation.parts || relation._contraction) return 'contraction';
    return relation.pos || '';
}
// A partner slot names a word type (verb, noun…) or describes one. Those that
// name a thing are noun phrases — "em + place" is em + casa — so they take the
// noun colour; a clause ("…") or "more / less" names no word type.
const FW_POS_SLOTS = ['noun', 'verb', 'adj', 'pron', 'prep', 'adv', 'det', 'conj', 'clitic', 'part'];
const FW_NOMINAL_SLOTS = new Set(['place', 'person', 'thing', 'time', 'reason', 'role', 'topic', 'endpoint', 'place / time', 'route / reason']);
function fwSlotType(relation, side) {
    const type = relation?.slotTypes?.[side];
    if (FW_POS_SLOTS.includes(type)) return type;
    const label = String(relation?.formulaHTML || '').match(new RegExp(`fw-token-${side}['"]>([^<]*)<`))?.[1];
    return label && FW_NOMINAL_SLOTS.has(label.trim().toLowerCase()) ? 'noun' : '';
}
// A pattern row's colour is its partner's word type; with no typed partner,
// the function word's own colour. No active row is left white.
function fwRowRgb(relation, fallbackPos) {
    const formula = String(relation?.formulaHTML || '');
    for (const side of ['v', 'c']) {
        if (!new RegExp(`fw-token-${side}['"]`).test(formula)) continue;
        const type = fwSlotType(relation, side);
        const rgb = type ? fwPresentation.posRgb?.(type) : null;
        if (rgb) return rgb;
    }
    return fwPresentation.posRgb?.(fwAccentPos(relation) || fallbackPos) || '';
}
function fwPartsHTML(parts) {
    return parts && parts.length === 2 ? `(${esc(parts[0])} + ${esc(parts[1])})` : '';
}
// Slots that name a word type (noun, verb, adjective…) take that type's
// colour: as a pill in the pattern row, as coloured words in the example.
// Anything else ("destination", "more, less or better", a clause) stays
// uncoloured. The function word itself is styled white by CSS.
function fwSlotHTML(html, relation, inPattern = false) {
    // A slot the pattern no longer names (e.g. the clause after "think + que")
    // stays plain text in the example rather than taking a colour.
    const formula = relation?.formulaHTML;
    // An unnamed continuation adds no information to a pattern (até + …).
    const pattern = inPattern ? String(html || '').replace(
        /\s*\+\s*(?:<span\b[^>]*>\s*(?:…|\.{3})\s*<\/span>|…|\.{3})/g, '') : String(html || '');
    let out = pattern.replace(/<span class=['"]fw-token-([vc])['"]>/g, (tag, side) => {
        if (formula && !new RegExp(`fw-token-${side}['"]`).test(formula)) return '<span>';
        const type = fwSlotType(relation, side);
        const rgb = type ? fwPresentation.posRgb?.(type) : null;
        if (!rgb) return `<span class="fw-token-${side} is-untyped">`;
        const pill = inPattern ? ' fw-slot-pill' : '';
        return `<span class="fw-token-${side}${pill}" data-pos="${type}" style="--slot-rgb: ${rgb}; color:rgb(${rgb})">`;
    });
    const pos = fwAccentPos(relation);
    if (pos) out = out.replace(/<span class=['"]fw-token-connector['"]>/g, `<span class="fw-token-connector" data-pos="${esc(pos)}">`);
    return out;
}
function fwCreditHTML(example) {
    if (example?.metadata?.source?.source_record_id) {
        return fwPresentation.provenanceHTML?.(example) || '';
    }
    return String(example?.source || '').startsWith('Original teaching example') ? 'Teaching example' : 'Source not verified';
}

function esc(str) {
    return String(str || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function shortGloss(raw) {
    const s = String(raw || '').trim();
    if (!s) return '';
    return s.split(/[,;/]/)[0].trim().toLowerCase();
}

function meaningOf(obj) {
    if (!obj) return '';
    if (typeof obj === 'string') return obj;
    return obj.gloss || obj.meaning || obj.translation || obj.definition || '';
}

/** Lookup a deterministic grammar-word definition for a card in the given language. */
export function getGrammarWordDefinition(cardOrWord, lang) {
    if (!cardOrWord || (typeof cardOrWord === 'object'
        && (cardOrWord.playlistId || cardOrWord.isChainChild))) return null;
    const wordKey = typeof cardOrWord === 'string'
        ? cardOrWord.trim().toLowerCase()
        : (cardOrWord.targetWord || cardOrWord.word || '').trim().toLowerCase();
    if (!wordKey) return null;

    const langKey = String(lang || 'pt').toLowerCase();
    const suite = GRAMMAR_WORDS[langKey] || PORTUGUESE_GRAMMAR_WORDS;
    const base = suite[wordKey] || null;
    if (!base || !syntaxTrialEnabled()) return base;
    const language = suite === SPANISH_GRAMMAR_WORDS ? 'es' : 'pt';
    const additions = FW_SYNTAX_TRIAL[language]?.[wordKey];
    if (!additions) return base;
    const relations = base.relations.map((relation, index) => {
        const extra = additions[index];
        if (!extra?.length) return relation;
        const existing = relation.examples || [];
        const ids = new Set(existing.map(example => example.example_id).filter(Boolean));
        const examples = [...extra.filter(example => !ids.has(example.example_id)), ...existing];
        return {...relation, examples, targetHTML: examples[0].targetHTML, translation: examples[0].translation};
    });
    return {...base, relations, uses: relations, syntaxTrial: true};
}

// Backward-compatibility alias:
export function getPortugueseGrammarDefinition(cardOrWord, lang) {
    return getGrammarWordDefinition(cardOrWord, lang || 'pt');
}

/** Determine if a card is a function word. */
export function isFunctionWordCard(card, lang) {
    if (!card || card.playlistId || card.isChainChild) return false;
    if (card.partOfSpeech === 'FW' || card.pos === 'FW' || card.functionWord) return true;
    return Boolean(getGrammarWordDefinition(card, lang));
}

export function isPortugueseGrammarWord(card, lang) {
    if (!card) return false;
    const isPt = !lang || lang === 'portuguese' || lang === 'pt' || lang === 'portuguese_brazilian';
    if (!isPt) return false;
    const wordKey = String(card.targetWord || card.word || card.lemma || '').trim().toLowerCase();
    return Boolean(PORTUGUESE_GRAMMAR_WORDS[wordKey]);
}

export function isSpanishGrammarWord(card, lang) {
    if (!card) return false;
    const isEs = lang === 'spanish' || lang === 'es';
    if (!isEs) return false;
    const wordKey = String(card.targetWord || card.word || card.lemma || '').trim().toLowerCase();
    return Boolean(SPANISH_GRAMMAR_WORDS[wordKey]);
}

export function getSpanishGrammarDefinition(card, lang) {
    return getGrammarWordDefinition(card, lang || 'es');
}

// Computes ambient glow CSS for any flashcard based on POS rules & FW signature glow
export function getCardAmbientGlow(card, lang, activePos, isSplitCard, getPosAccentRgbFn) {
    const getRgb = getPosAccentRgbFn || (typeof window !== 'undefined' ? window.getPosAccentRgb : null) || (() => '148, 163, 184');

    // 1. Companion card ("Card 1 of 2"): single POS color matching active companion card
    if (isSplitCard && card?.splitInfo) {
        const splitPos = card.splitInfo.pos || card.partOfSpeech || activePos;
        const rgb = getRgb(splitPos);
        return `radial-gradient(circle at 50% 20%, rgba(${rgb}, 0.18), transparent 70%)`;
    }

    // 2. Merged lemmas: merged cards represent a single unified lexeme (verb).
    // Always emits a single centered radial glow in the verb color (green).
    if (card?.mergedLemma) {
        const mergedPos = (card.partOfSpeech && !/verb|aux/i.test(card.partOfSpeech))
            ? card.partOfSpeech
            : (activePos || card.partOfSpeech || 'VERB');
        const rgb = getRgb(mergedPos);
        return `radial-gradient(circle at 50% 20%, rgba(${rgb}, 0.18), transparent 70%)`;
    }

    const NON_LEXICAL_POS = new Set(['MWE', 'CLITIC', 'SENSE_CYCLE', 'EXAMPLE_ONLY', 'PHRASE']);

    const isRareMeaning = m => {
        if (!m) return true;
        if (m.isRareSense || m.lowShare || m.rare || m.unassigned || m.exampleOnly) return true;
        if (m.assignment_method === 'unassigned') return true;
        const prom = String(m.prominenceLabel || '').trim().toLowerCase();
        if (prom === 'rare') return true;
        if (typeof window !== 'undefined' && typeof window.getSenseProminenceInfo === 'function') {
            try {
                if (window.getSenseProminenceInfo(m)?.key === 'rare') return true;
            } catch (_) {}
        }
        const share = Number(m.shownShare ?? m.percentage);
        const hasExplicitShare = (m.shownShare != null || m.percentage != null) && !isNaN(share);
        const hasExamples = Boolean(
            m.targetSentence ||
            (Array.isArray(m.allExamples) && m.allExamples.length > 0) ||
            (Array.isArray(m.examples) && m.examples.length > 0)
        );
        if (hasExplicitShare && share <= 0) return true;
        if (!hasExamples && hasExplicitShare && share < 0.10) return true;
        return false;
    };

    const cardMeanings = (card?.meanings || []).filter(m => {
        if (!m) return false;
        const pos = m.pos === 'SENSE_CYCLE' ? (m.cycle_pos || '') : (m.pos || '');
        if (!pos || NON_LEXICAL_POS.has(String(pos).toUpperCase())) return false;
        if (typeof window !== 'undefined' && typeof window.isHiddenExpressionOnParent === 'function' && window.isHiddenExpressionOnParent(card, m)) return false;
        return true;
    });

    const nonRareMeanings = cardMeanings.filter(m => !isRareMeaning(m));
    const candidateMeanings = nonRareMeanings.length > 0 ? nonRareMeanings : cardMeanings;

    const totalWeight = candidateMeanings.reduce(
        (sum, m) => sum + (Number(m.shownShare ?? m.percentage) || 0),
        0
    );

    const rgbWeights = new Map();
    const rgbOrder = [];

    for (const m of candidateMeanings) {
        const pos = m.pos === 'SENSE_CYCLE' ? (m.cycle_pos || '') : (m.pos || '');
        const rgb = getRgb(pos);
        if (!rgb) continue;
        const weight = Number(m.shownShare ?? m.percentage) || 0;
        if (!rgbWeights.has(rgb)) {
            rgbWeights.set(rgb, 0);
            rgbOrder.push(rgb);
        }
        rgbWeights.set(rgb, rgbWeights.get(rgb) + weight);
    }

    let distinctRgb = rgbOrder;
    if (totalWeight > 0 && rgbOrder.length > 1) {
        const significant = rgbOrder.filter(rgb => (rgbWeights.get(rgb) / totalWeight) >= 0.10);
        if (significant.length > 0) {
            distinctRgb = significant;
        }
    }

    if (distinctRgb.length === 0) {
        let fallbackPos = card?.partOfSpeech;
        if (!fallbackPos || String(fallbackPos).toUpperCase() === 'FW') {
            const gw = typeof getGrammarWordDefinition === 'function' ? getGrammarWordDefinition(card, lang) : null;
            fallbackPos = gw?.role || gw?.pos || card?.pos || activePos;
        }
        distinctRgb = [getRgb(fallbackPos || activePos)];
    }

    const activeRgb = activePos ? getRgb(activePos) : null;
    if (activeRgb && distinctRgb.includes(activeRgb) && distinctRgb[0] !== activeRgb) {
        distinctRgb = [activeRgb, ...distinctRgb.filter(c => c !== activeRgb)];
    }

    // Single POS color: single centered radial glow
    if (distinctRgb.length <= 1) {
        return `radial-gradient(circle at 50% 20%, rgba(${distinctRgb[0]}, 0.18), transparent 70%)`;
    }

    // 2 POS colors: multi-corner glow
    if (distinctRgb.length === 2) {
        return `radial-gradient(circle at 22% 16%, rgba(${distinctRgb[0]}, 0.17), transparent 58%), radial-gradient(circle at 78% 16%, rgba(${distinctRgb[1]}, 0.17), transparent 58%)`;
    }

    // 3 or more POS colors
    return `radial-gradient(circle at 18% 16%, rgba(${distinctRgb[0]}, 0.15), transparent 50%), radial-gradient(circle at 50% 12%, rgba(${distinctRgb[1]}, 0.15), transparent 50%), radial-gradient(circle at 82% 16%, rgba(${distinctRgb[2]}, 0.15), transparent 50%)`;
}

// Active state for deterministic card back navigation
let _activeWordKey = null;
let _activeRelIndex = 0;
let _activeExampleIndex = 0;

export function selectFunctionWordRelation(relIdx) {
    _activeRelIndex = Number(relIdx) || 0;
    _activeExampleIndex = 0;
    refreshFunctionWordCardBack();
}

// Backward compatibility alias:
export function selectFunctionWordUse(useIdx) {
    selectFunctionWordRelation(useIdx);
}

function isArtistExample(item) {
    if (!item) return false;
    if (item.channel === 'artist') return true;
    if (item?.metadata?.source?.artist || item.artist) return true;
    const src = String(item.source || '').trim();
    if (src.includes(' · ') || /^(Polyglot|Portuguese Playlist|Rosalía|Artist)/i.test(src)) {
        return true;
    }
    return false;
}

function matchesArtist(item, artistName) {
    if (!item || !artistName) return false;
    const a = String(item?.metadata?.source?.artist || item?.source || item?.artist || '').trim().toLowerCase();
    if (!a) return false;
    const art = String(artistName).trim().toLowerCase();
    if (!art) return false;
    return a.includes(art) || art.includes(a);
}

const KNOWN_SAFE_PROVENANCE_SOURCES = new Set([
    'conversation',
    'dialogue',
    'everyday dialogue',
    'everyday speech',
    'literature',
    'opensubtitles',
    'subtitles',
    'tatoeba',
    'teaching example',
    'original teaching example',
]);

function isExplicitlySafeCurriculumExample(item) {
    if (!item) return false;
    if (isArtistExample(item)) return false;
    if (!item.targetHTML && !item.target) return false;

    // Positive curriculum or speech provenance is strictly required
    if (item.channel === 'speech' || item.channel === 'curriculum') {
        return true;
    }
    const metaSource = item.metadata?.source;
    if (metaSource) {
        if (metaSource.channel === 'speech' || metaSource.channel === 'curriculum') {
            return true;
        }
        const adapter = String(metaSource.adapter || '').trim().toLowerCase();
        if (adapter.startsWith('tatoeba') || adapter.startsWith('opensubtitles') || adapter.startsWith('speech')) {
            return true;
        }
        const metaName = String(metaSource.name || '').trim().toLowerCase();
        if (KNOWN_SAFE_PROVENANCE_SOURCES.has(metaName) || metaName.startsWith('tatoeba') || metaName.startsWith('opensubtitles')) {
            return true;
        }
    }
    const src = String(item.source || '').trim().toLowerCase();
    if (!src) return false; // Missing/empty source is never positive proof of curriculum provenance
    if (KNOWN_SAFE_PROVENANCE_SOURCES.has(src) || src.startsWith('tatoeba') || src.startsWith('opensubtitles') || src.startsWith('original teaching example')) {
        return true;
    }
    return false;
}

function getRelationExamples(relation, cardOrContext) {
    if (!relation) return [];
    if (syntaxTrialEnabled() || relation.syntaxTrial || cardOrContext?.syntaxTrial) {
        return relation.examples || [];
    }

    let channel = 'speech';
    let artistName = '';

    if (typeof window !== 'undefined') {
        const active = window.activeArtist || (typeof activeArtist !== 'undefined' ? activeArtist : null);
        if (active) {
            channel = 'artist';
            artistName = String(active.name || active.slug || '').trim().toLowerCase();
        }
    }
    if (cardOrContext) {
        if (cardOrContext.channel) channel = cardOrContext.channel;
        else if (cardOrContext.artist || cardOrContext.song || cardOrContext.is_artist) channel = 'artist';
        if (cardOrContext.artist) artistName = String(cardOrContext.artist).trim().toLowerCase();
    }

    if (channel === 'artist') {
        // If an artist is selected, match to the selected artist ONLY
        if (artistName) {
            if (relation.artist_examples_by_artist) {
                for (const [art, exs] of Object.entries(relation.artist_examples_by_artist)) {
                    const a = String(art || '').trim().toLowerCase();
                    if (a && (a.includes(artistName) || artistName.includes(a))) {
                        if (exs && exs.length > 0) return exs;
                    }
                }
            }
            if (relation.artist_examples && relation.artist_examples.length > 0) {
                const matched = relation.artist_examples.filter(ex => matchesArtist(ex, artistName));
                if (matched.length > 0) return matched;
            }
            // When the selected artist has no matches, do NOT return another artist's lyrics!
            // Prefer verified speech examples first
            if (relation.speech_examples && relation.speech_examples.length > 0) {
                return relation.speech_examples;
            }
            // Fallback: only include matches for the selected artist OR examples with positive curriculum/speech provenance
            const safeExamples = (relation.examples || []).filter(ex => {
                if (matchesArtist(ex, artistName)) return true;
                return isExplicitlySafeCurriculumExample(ex);
            });
            if (safeExamples.length > 0) return safeExamples;
            if (isExplicitlySafeCurriculumExample(relation)) {
                return [relation];
            }
            return [];
        } else if (relation.artist_examples && relation.artist_examples.length > 0) {
            return relation.artist_examples;
        }
    } else {
        if (relation.speech_examples && relation.speech_examples.length > 0) {
            return relation.speech_examples;
        }
    }

    const baseline = (relation.examples && relation.examples.length > 0)
        ? relation.examples
        : (isExplicitlySafeCurriculumExample(relation) ? [relation] : []);
    return baseline;
}

export function cycleFunctionWordExample() {
    const container = document.querySelector('.fw-deterministic-card');
    if (!container) return;
    const cardWord = container.dataset.word;
    const lang = container.dataset.lang || 'pt';
    const data = getGrammarWordDefinition(cardWord, lang);
    if (!data) return;

    const relations = data.relations || data.uses || [];
    if (_activeRelIndex >= relations.length) _activeRelIndex = 0;
    const currentRel = relations[_activeRelIndex];
    const deckContext = {
        channel: container.dataset.deck || 'speech',
        artist: container.dataset.artist || ''
    };
    const examples = getRelationExamples(currentRel, deckContext);
    if (examples.length === 0) {
        return;
    }
    if (examples.length === 1) {
        const curEx = examples[0];
        const plain = (curEx?.targetHTML || curEx?.target || '').replace(/<[^>]+>/g, '');
        window.speakTargetSentence?.() || window.speakText?.(plain);
        return;
    }

    _activeExampleIndex = (_activeExampleIndex + 1) % examples.length;
    refreshFunctionWordCardBack();

    const curEx = examples[_activeExampleIndex];
    if (curEx) {
        const plain = (curEx.targetHTML || curEx.target || '').replace(/<[^>]+>/g, '');
        window.speakText?.(plain);
    }
}

function renderFwTicks(total, current) {
    if (total < 2) return '';
    const ticks = Array.from({ length: total }, (_, i) =>
        `<span class="example-tick${i === current ? ' is-current' : ''}"></span>`
    ).join('');
    return `<div class="example-ticks" role="img" aria-label="Example ${current + 1} of ${total}">${ticks}</div>`;
}

function refreshFunctionWordCardBack() {
    const container = document.querySelector('.fw-deterministic-card');
    if (!container) return;
    const cardWord = container.dataset.word;
    const lang = container.dataset.lang || 'pt';
    const data = getGrammarWordDefinition(cardWord, lang);
    if (!data) return;

    const relations = data.relations || data.uses || [];
    if (_activeRelIndex >= relations.length) _activeRelIndex = 0;
    const currentRel = relations[_activeRelIndex];

    // Update container POS and ambient glow
    const accentPos = fwAccentPos(currentRel);
    if (accentPos) {
        if (container.dataset) container.dataset.pos = accentPos;
        const rgb = fwPresentation.posRgb?.(accentPos);
        if (rgb && container.style?.setProperty) container.style.setProperty('--sense-match-rgb', rgb);
    }

    // Update relations selection
    container.querySelectorAll('.fw-relation-box').forEach((btn, i) => {
        const isSelected = i === _activeRelIndex;
        btn.setAttribute('aria-pressed', String(isSelected));
        btn.classList.toggle('is-selected', isSelected);
    });

    // Hybrid words (nos = em + os only in its contraction pattern) show their
    // parts beside the heading while that pattern is active.
    const dynamicParts = container.querySelector('.fw-heading-parts.is-dynamic');
    if (dynamicParts) {
        const text = fwPartsHTML(currentRel?.parts);
        dynamicParts.innerHTML = text;
        dynamicParts.hidden = !text;
    }

    // Get current example from deck-specific examples array
    const deckContext = {
        channel: container.dataset.deck || 'speech',
        artist: container.dataset.artist || ''
    };
    const examples = getRelationExamples(currentRel, deckContext);
    if (_activeExampleIndex >= examples.length) _activeExampleIndex = 0;
    const currentEx = examples.length > 0 ? (examples[_activeExampleIndex] || examples[0]) : null;

    // Update sentence target and translation
    const sentenceEl = container.querySelector('.fw-sentence-target');
    if (sentenceEl) {
        if (currentEx) {
            sentenceEl.innerHTML = fwSlotHTML(currentEx.targetHTML || currentEx.target || '', currentRel);
        } else {
            const artName = deckContext.artist ? ` for ${deckContext.artist}` : '';
            sentenceEl.innerHTML = `<span class="fw-shortage-msg">No matching examples found${esc(artName)}</span>`;
        }
    }

    const transEl = container.querySelector('.fw-sentence-translation');
    if (transEl) {
        transEl.textContent = currentEx ? (currentEx.translation || '') : 'Example shortage for this deck pattern';
    }

    const creditStartEl = container.querySelector('.fw-credit-start');
    if (creditStartEl) {
        creditStartEl.innerHTML = currentEx ? fwCreditHTML(currentEx) : '<span class="fw-shortage-badge">Shortage</span>';
    }

    const ticksContainer = container.querySelector('.fw-sentence-ticks-container');
    if (ticksContainer) {
        ticksContainer.innerHTML = renderFwTicks(examples.length, _activeExampleIndex);
    }
}

// Pattern rows: the meaning sits beside the pattern when both fit, else beneath it.
export function fitFunctionWordRows(root = document) {
    root.querySelectorAll?.('.fw-relations-list').forEach(list => {
        const boxes = [...list.querySelectorAll('.fw-relation-box')];
        boxes.forEach(box => box.classList.remove('is-stacked'));
        // Only the row that needs the space stacks; short neighbours stay inline.
        boxes.forEach(box => {
            const f = box.querySelector('.fw-relation-formula');
            const m = box.querySelector('.fw-relation-meaning');
            box.classList.toggle('is-stacked', Boolean(f && m
                && m.offsetTop > f.offsetTop + f.offsetHeight / 2));
        });
    });
}
if (typeof window !== 'undefined' && typeof MutationObserver !== 'undefined') {
    let queued = false;
    const refit = () => { if (queued) return; queued = true; requestAnimationFrame(() => { queued = false; fitFunctionWordRows(); }); };
    new MutationObserver(refit).observe(document.documentElement, { childList: true, subtree: true });
    window.addEventListener('resize', refit);
}

// Make functions available globally for onclick handlers
if (typeof window !== 'undefined') {
    window.selectFunctionWordRelation = selectFunctionWordRelation;
    window.selectFunctionWordUse = selectFunctionWordUse;
    window.cycleFunctionWordExample = cycleFunctionWordExample;
    window.getCardAmbientGlow = getCardAmbientGlow;
    window.FW_SIGNATURE_GLOW_RGB = FW_SIGNATURE_GLOW_RGB;
}

export function functionWordLabelText(label) {
    if (!label || !label.value) return '';
    if (label.kind === 'unit') {
        const gloss = shortGloss(meaningOf(label.gloss));
        return gloss ? `${label.value} · ${gloss}` : label.value;
    }
    const name = ROLE_NAMES[label.value] || label.value.replace(/_/g, ' ');
    const gloss = label.value === 'prep' ? String(label.gloss || '').replace(/\s*\(\+ verb\)$/, '') : label.gloss;
    return gloss && gloss !== name ? `${name} · ${gloss}` : name;
}

/** Card-back block replacing the sense list: what the word does, and its constructions. */
export function functionWordBlockHTML(card, lang) {
    // Live source examples have no assigned grammatical construction. Keep
    // their dialogue/song lines on the ordinary card instead of replacing
    // them with the Speech deck's fixed dictionary illustrations.
    if (card?.playlistId || card?.isChainChild) return '';
    const fwData = getGrammarWordDefinition(card, lang) || (card?.functionWord?.uses ? card.functionWord : null);

    // 1. Deterministic layout for Portuguese and Spanish focus grammar words
    if (fwData && (fwData.relations || fwData.uses)) {
        const wordKey = fwData.word || card.targetWord || card.word;
        if (_activeWordKey !== wordKey) {
            _activeWordKey = wordKey;
            _activeRelIndex = 0;
            _activeExampleIndex = 0;
        }

        const relations = fwData.relations || fwData.uses || [];
        if (_activeRelIndex >= relations.length) _activeRelIndex = 0;
        const currentRel = relations[_activeRelIndex];

        // Contraction parts sit beside the word on one line: "del (de + el)".
        // Hybrid words (nos) show theirs only while the contraction pattern is active.
        const partsHTML = fwData.parts
            ? `<span class="fw-heading-parts">${fwPartsHTML(fwData.parts)}</span>`
            : `<span class="fw-heading-parts is-dynamic"${fwPartsHTML(currentRel?.parts) ? '' : ' hidden'}>${fwPartsHTML(currentRel?.parts)}</span>`;

        // One row per pattern: the formula, with its plain meaning beneath. The
        // longer rule stays on the row as its tooltip and accessible description.
        const relationsHTML = relations.map((rel, i) => {
            const isSelected = i === _activeRelIndex;
            const meaning = rel.tag || '';
            const rule = rel.rule || rel.description || '';
            const rowRgb = fwRowRgb(rel, card?.pos || card?.meanings?.[0]?.pos);
            return `
                <button type="button" class="fw-relation-box${isSelected ? ' is-selected' : ''}" data-pos="${esc(rel.pos || '')}" aria-pressed="${isSelected}"${rowRgb ? ` style="--fw-row-rgb: ${rowRgb}"` : ''}${rule ? ` title="${esc(rule)}"` : ''} onclick="event.stopPropagation(); window.selectFunctionWordRelation(${i})">
                    <div class="fw-relation-formula">${fwSlotHTML(rel.formulaHTML || esc(rel.formula || ''), rel, true)}</div>
                    ${meaning ? `<p class="fw-relation-meaning">${esc(meaning)}</p>` : ''}
                </button>`;
        }).join('');

        const deckContext = {
            channel: (card?.artist || card?.channel === 'artist' || (typeof window !== 'undefined' && window.activeArtist)) ? 'artist' : 'speech',
            artist: card?.artist || (typeof window !== 'undefined' && window.activeArtist?.name) || ''
        };
        const examples = getRelationExamples(currentRel, deckContext);
        if (_activeExampleIndex >= examples.length) _activeExampleIndex = 0;
        const currentEx = examples.length > 0 ? (examples[_activeExampleIndex] || examples[0]) : null;

        let targetHTML = '';
        let translationText = '';
        let creditHTML = '';
        if (currentEx) {
            targetHTML = fwSlotHTML(currentEx.targetHTML || esc(currentEx.target || ''), currentRel);
            translationText = esc(currentEx.translation || '');
            creditHTML = fwCreditHTML(currentEx);
        } else {
            const artName = deckContext.artist ? ` for ${deckContext.artist}` : '';
            targetHTML = `<span class="fw-shortage-msg">No matching examples found${esc(artName)}</span>`;
            translationText = 'Example shortage for this deck pattern';
            creditHTML = '<span class="fw-shortage-badge">Shortage</span>';
        }
        const ticksHTML = renderFwTicks(examples.length, _activeExampleIndex);

        return `
            <div class="fw-deterministic-card" data-word="${esc(wordKey)}" data-lang="${esc(lang || 'pt')}" data-pos="${esc(fwAccentPos(currentRel))}" data-deck="${esc(deckContext.channel)}" data-artist="${esc(deckContext.artist)}" style="--sense-match-rgb: ${fwPresentation.posRgb?.(fwAccentPos(currentRel) || card?.pos || card?.meanings?.[0]?.pos) || 'var(--accent-primary-rgb)'};">
                <div class="fw-header">
                    <h2 class="fw-heading"><span class="fw-heading-word">${esc(wordKey)}</span>${partsHTML}</h2>
                    ${fwData.syntaxTrial ? '<div class="fw-section-header">Reviewed example trial</div>' : ''}
                    <div class="fw-patterns-label">Example patterns</div>
                </div>
                <div class="fw-relations-list">
                    ${relationsHTML}
                </div>
                <div class="fw-sentence-panel" onclick="event.stopPropagation(); window.cycleFunctionWordExample();">
                    <div class="fw-sentence-target">${targetHTML}</div>
                    <div class="fw-sentence-translation">${translationText}</div>
                    <div class="fw-example-credit-row">
                        <span class="fw-credit-start">${creditHTML}</span>
                        <div class="fw-sentence-ticks-container">${ticksHTML}</div>
                    </div>
                </div>
            </div>`;
    }

    // Uncovered words keep the normal meaning rows; legacy summary chips are retired.
    return '';
}


/** The label under one example's translation; empty when the rules gave none. */
export function functionWordExampleHTML(example) {
    const label = example?.metadata?.function_word;
    const text = functionWordLabelText(label);
    if (!text) return '';
    const kind = label.kind === 'unit' ? 'fw-chip-pattern' : 'fw-chip-role';
    return `<div class="fw-example-label"><span class="fw-chip ${kind}">${esc(text)}</span></div>`;
}
